CREATE OR REPLACE FUNCTION public.publish_monitor_schedule_prepare(a uuid, p_job uuid, p_scheduled_at timestamp with time zone, p_preview text, p_media_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
